		} else {
			addr = parseDefaultProxyHeaders(r)
		}

		if isValidAddr(addr) {
			return addr
		}
	}

	return r.RemoteAddr
}

// isValidAddr checks if the Addr is a valid IP or IP:port.
func isValidAddr(addr string) bool {
	if addr == "" {
		return false
	}

	ip, _, err := net.SplitHostPort(addr)
	if err != nil {
		return net.ParseIP(addr) != nil
	}

	return net.ParseIP(ip) != nil
}

func parseDefaultProxyHeaders(r *http.Request) string {
	var addr string

	if fwd := r.Header.Get(xForwardedForHeader); fwd != "" {
		addr = extractFirstMatchFromIPList(fwd)
	} else if fwd := r.Header.Get(xRealIPHeader); fwd != "" {
		addr = extractFirstMatchFromIPList(fwd)
	} else if fwd := r.Header.Get(forwardedHeader); fwd != "" {
		// See: https://tools.ietf.org/html/rfc7239.
		addr = parseForwardedHeader(fwd)
	}

	return addr
}

func extractFirstMatchFromIPList(ipList string) string {
	if ipList == "" {
		return ""
	}
	s := strings.Index(ipList, ",")
	if s == -1 {
		s = len(ipList)
	}

	return ipList[:s]
}

func parseForwardedHeader(fwd string) string {
	// According to RFC 7239, the Forwarded header can contain multiple
	// values separated by commas. Each value can have multiple parameters
	// separated by semicolons.
	//
	// Example: Forwarded: for=192.0.2.43, for=198.51.100.17;by=203.0.113.60

	// Split by comma to get individual forwarded elements
	elements := strings.Split(fwd, ",")

	// Process the first element to find the "for=" parameter
	if len(elements) > 0 {
		firstElement := strings.TrimSpace(elements[0])

		// Split by semicolon to get individual parameters
		params := strings.Split(firstElement, ";")

		// Look for the "for=" parameter
		for _, param := range params {
			trimmedParam := strings.TrimSpace(param)
			lowerParam := strings.ToLower(trimmedParam)

			if strings.HasPrefix(lowerParam, "for=") {
				// Extract the value after "for="
				addr := trimmedParam[4:]

